import{_ as t,o,c as r,a3 as n}from"./chunks/framework.D1iekJsc.js";const u=JSON.parse('{"title":"OpenCode Zen","description":"OpenCode Zen Modell-Gateway — Website, Free-Modelle, Bezahlung und Eintrag in MiniTavern.","frontmatter":{"title":"OpenCode Zen","description":"OpenCode Zen Modell-Gateway — Website, Free-Modelle, Bezahlung und Eintrag in MiniTavern.","head":[["meta",{"name":"keywords","content":"Tavern,AI Tavern,MiniTavern,AI Begleiter,AI Freund,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobil,Silly Tavern Android,Silly Tavern iOS,AI Roleplay,Charakterkarte,AI Chat,mobiles AI,Offline-AI,AI Geschichte,lokales LLM,Ollama,LM Studio,Lorebook,Regex,BYOK,Handbuch,Anleitung"}],["meta",{"property":"og:title","content":"OpenCode Zen · MiniTavern Docs"}],["meta",{"property":"og:description","content":"OpenCode Zen Modell-Gateway — Website, Free-Modelle, Bezahlung und Eintrag in MiniTavern."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/de/free-cloud/opencode-zen"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/de/free-cloud/opencode-zen"}]]},"headers":[],"relativePath":"de/free-cloud/opencode-zen.md","filePath":"de/free-cloud/opencode-zen.md","lastUpdated":1787224147000}'),a={name:"de/free-cloud/opencode-zen.md"};function d(i,e,l,s,c,h){return o(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="opencode-zen" tabindex="-1">OpenCode Zen <a class="header-anchor" href="#opencode-zen" aria-label="Permalink to &quot;OpenCode Zen&quot;">​</a></h1><p>AI-Gateway des <a href="https://opencode.ai/" target="_blank" rel="noreferrer">OpenCode</a>-Teams: kuratierte, getestete Coding-Modelle, pay-per-request; dazu einige <strong>Free</strong>-Textmodelle. Nutzbar auch außerhalb von OpenCode (inkl. MiniTavern). Offiziell: <a href="https://opencode.ai/docs/zh-cn/zen/" target="_blank" rel="noreferrer">Zen-Doku (简体)</a>.</p><blockquote><p>Zen ist <strong>kein</strong> dauerhaft kostenloses All-Inclusive: Flagship meist Pay-as-you-go, oft Billing/Aufladung; Free-Modelle unten für Tests innerhalb Caps. Policy laut Website.</p></blockquote><h2 id="website-einstiege" tabindex="-1">Website &amp; Einstiege <a class="header-anchor" href="#website-einstiege" aria-label="Permalink to &quot;Website &amp; Einstiege&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Ressource</th><th>Adresse</th></tr></thead><tbody><tr><td>Zen-Übersicht</td><td><a href="https://opencode.ai/en/zen" target="_blank" rel="noreferrer">opencode.ai/zen</a></td></tr><tr><td>Login / Key</td><td><a href="https://opencode.ai/auth" target="_blank" rel="noreferrer">opencode.ai/auth</a></td></tr><tr><td>Doku (简体)</td><td><a href="https://opencode.ai/docs/zh-cn/zen/" target="_blank" rel="noreferrer">opencode.ai/docs/zh-cn/zen</a></td></tr><tr><td>Modell-Metadaten</td><td><code>https://opencode.ai/zen/v1/models</code></td></tr><tr><td>API Base URL (OpenAI-kompatibel)</td><td><code>https://opencode.ai/zen/v1</code></td></tr></tbody></table><h2 id="free-holen" tabindex="-1">Free holen <a class="header-anchor" href="#free-holen" aria-label="Permalink to &quot;Free holen&quot;">​</a></h2><ol><li><a href="https://opencode.ai/auth" target="_blank" rel="noreferrer">opencode.ai/auth</a> (GitHub / Google) anmelden.</li><li>Nach Konsole <strong>API Key</strong> erzeugen. Oft Billing-Infos nötig; bei Free Autotop-up prüfen und ggf. abschalten.</li><li>MiniTavern <strong>Custom (OpenAI)</strong>, Base URL <code>https://opencode.ai/zen/v1</code>, Free-ID unten.</li></ol><table tabindex="0"><thead><tr><th>Punkt</th><th>Hinweis</th></tr></thead><tbody><tr><td>Free</td><td>Modelle mit Preis <strong>Free</strong> (innerhalb OpenCode-Caps); Feedback — können sich ändern oder verschwinden</td></tr><tr><td>Bezahlt</td><td>Pay-as-you-go; unter $5 oft Auto-Aufladung $20 (änderbar/abschaltbar)</td></tr><tr><td>Kreditkarte</td><td>«How it works» verlangt Billing; Konsole gilt</td></tr><tr><td>Privacy</td><td>Free (Big Pickle, MiMo Free, Hy3, Nemotron Free, Muse Contributor Free) ggf. Logs zur Verbesserung; Nemotron = NVIDIA-Trial — keine Geheimnisse</td></tr></tbody></table><p>Preise &amp; Deprecation: <a href="https://opencode.ai/docs/zh-cn/zen/#%E5%AE%9A%E4%BB%B7" target="_blank" rel="noreferrer">Zen · Pricing</a>.</p><h2 id="modellliste" tabindex="-1">Modellliste <a class="header-anchor" href="#modellliste" aria-label="Permalink to &quot;Modellliste&quot;">​</a></h2><p>IDs <strong>case-sensitive</strong>. Zen routet je Anbieter über <code>/chat/completions</code>, <code>/responses</code>, <code>/messages</code> oder Gemini-Pfade. MiniTavern <strong>Custom (OpenAI)</strong> = Chat Completions — bevorzugt <strong>OpenAI-kompatible</strong> Zeilen.</p><p>Vollständige Tabelle: <a href="https://opencode.ai/docs/zh-cn/zen/#%E7%AB%AF%E7%82%B9" target="_blank" rel="noreferrer">Zen · Endpoints</a>; oder <code>GET https://opencode.ai/zen/v1/models</code>.</p><h3 id="text-·-free-zuerst-testen" tabindex="-1">Text · Free (zuerst testen) <a class="header-anchor" href="#text-·-free-zuerst-testen" aria-label="Permalink to &quot;Text · Free (zuerst testen)&quot;">​</a></h3><p>Alle über <code>…/v1/chat/completions</code> außer Muse Contributor Free (Responses).</p><table tabindex="0"><thead><tr><th>Modell-ID</th><th>Hinweis</th></tr></thead><tbody><tr><td><code>mimo-v2.5-free</code></td><td>Xiaomi MiMo V2.5 Free</td></tr><tr><td><code>hy3-free</code></td><td>Hy3 Free</td></tr><tr><td><code>big-pickle</code></td><td>Stealth-Modell, Free</td></tr><tr><td><code>nemotron-3-ultra-free</code></td><td>NVIDIA Nemotron Trial — keine Geheimnisse</td></tr><tr><td><code>nemotron-3.5-lightning-free</code></td><td>dasselbe</td></tr><tr><td><code>muse-spark-1.2-contributor-free</code></td><td>Contributor Free; <code>/responses</code> — <strong>MiniTavern-Test ggf. ungeeignet</strong>; Prompts dürfen Meta trainieren</td></tr></tbody></table><h3 id="text-·-bezahlt-openai-kompatibel-optional" tabindex="-1">Text · bezahlt, OpenAI-kompatibel (optional) <a class="header-anchor" href="#text-·-bezahlt-openai-kompatibel-optional" aria-label="Permalink to &quot;Text · bezahlt, OpenAI-kompatibel (optional)&quot;">​</a></h3><p>Gleiche Base URL nach Aufladung:</p><table tabindex="0"><thead><tr><th>Modell-ID</th><th>Hinweis</th></tr></thead><tbody><tr><td><code>deepseek-v4-flash</code> / <code>deepseek-v4-pro</code></td><td>DeepSeek (Peak / Off-Peak)</td></tr><tr><td><code>glm-5.1</code> / <code>glm-5.2</code> / <code>glm-5</code></td><td>Zhipu GLM</td></tr><tr><td><code>kimi-k2.5</code> / <code>kimi-k2.6</code> / <code>kimi-k2.7-code</code> / <code>kimi-k3</code></td><td>Kimi</td></tr><tr><td><code>minimax-m2.5</code> / <code>minimax-m2.7</code> / <code>minimax-m3</code></td><td>MiniMax</td></tr></tbody></table><h3 id="andere-protokolle-in-minitavern-vorsichtig" tabindex="-1">Andere Protokolle (in MiniTavern vorsichtig) <a class="header-anchor" href="#andere-protokolle-in-minitavern-vorsichtig" aria-label="Permalink to &quot;Andere Protokolle (in MiniTavern vorsichtig)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Typ</th><th>Beispiel-IDs</th><th>Endpoint</th></tr></thead><tbody><tr><td>GPT</td><td><code>gpt-5.5</code>, <code>gpt-5.4-nano</code> …</td><td><code>/zen/v1/responses</code></td></tr><tr><td>Claude</td><td><code>claude-sonnet-4-6</code>, <code>claude-haiku-4-5</code> …</td><td><code>/zen/v1/messages</code></td></tr><tr><td>Gemini</td><td><code>gemini-3-flash</code> …</td><td><code>/zen/v1/models/&lt;id&gt;</code></td></tr></tbody></table><p>Nicht derselbe Pfad wie OpenAI Chat Completions; Roleplay bevorzugt Free oder OpenAI-kompatible IDs oben. Claude: App <strong>Claude(Anthropic)</strong> mit offiziellem Key oder <a href="/ultra_guides/de/free-cloud/aihubmix">AIHubMix</a>.</p><h3 id="bild-video" tabindex="-1">Bild / Video <a class="header-anchor" href="#bild-video" aria-label="Permalink to &quot;Bild / Video&quot;">​</a></h3><p>Zen-Katalog ist vor allem <strong>Sprachmodelle</strong> — <strong>kein</strong> separates Free-Bild/Video. Bild: <a href="/ultra_guides/de/free-cloud/agnes-ai">Agnes AI</a>, <a href="/ultra_guides/de/free-cloud/aihubmix">AIHubMix</a> oder <a href="/ultra_guides/de/free-cloud/#kostenlose-bildgenerierung">Kostenlose Bildgenerierung</a>.</p><h2 id="eintrag-in-minitavern" tabindex="-1">Eintrag in MiniTavern <a class="header-anchor" href="#eintrag-in-minitavern" aria-label="Permalink to &quot;Eintrag in MiniTavern&quot;">​</a></h2><p>Allgemein: <a href="/ultra_guides/de/manual/model-link">Modellverbindung</a>.</p><p>Pfad: <strong>Einstellungen → Modelle → Modellverbindung → Neu</strong></p><ol><li>Plattform <strong>Custom (OpenAI)</strong></li><li>Base URL: <code>https://opencode.ai/zen/v1</code></li><li>API Key</li><li>Modell <code>mimo-v2.5-free</code> (oder andere Free / chat-kompatible ID)</li><li><strong>Testen</strong> → dann als Standard</li></ol><blockquote><p>Test fehlgeschlagen: keine GPT-Responses-/Claude-Messages-ID; Autotop-up aus, Free erneut; <a href="/ultra_guides/de/manual/errors">Fehlercodes</a>.</p></blockquote><h2 id="verwandte-kapitel" tabindex="-1">Verwandte Kapitel <a class="header-anchor" href="#verwandte-kapitel" aria-label="Permalink to &quot;Verwandte Kapitel&quot;">​</a></h2><ul><li><a href="/ultra_guides/de/free-cloud/">Kostenlose Cloud Übersicht</a></li><li><a href="/ultra_guides/de/free-cloud/aihubmix">AIHubMix</a> — ein Key für viele <code>*-free</code> + Bild</li><li><a href="/ultra_guides/de/free-cloud/agnes-ai">Agnes AI</a></li><li><a href="/ultra_guides/de/manual/model-link">Modellverbindung</a></li></ul>',30)])])}const g=t(a,[["render",d]]);export{u as __pageData,g as default};
